;=============================================================================
; Battletoads & Double Dragon - The Ultimate Team (E) - sound engine, bank 3
; Rare, 1993. Labeled disassembly generated by tool/gen_disasm.py.
;
; Covers $8952-$B360 and $C05E-$CFDF (the gap $B361-$C05D is game code).
; Assemble with:
;   ca65 dd_sound.asm -o dd_sound.o && ld65 -C dd_sound.cfg dd_sound.o -o dd_sound
; and compare dd_sound.0.bin / dd_sound.1.bin with the ROM (bank 3 = file
; offset $0C010; $8952 -> $0C962, $C05E -> $1006E).
;
; Far-call interface (bank-0 stub $FFCB: X = jump-table offset, Y = bank 3):
;   X=$03 Music_Init  ($39 = song)      X=$06 Music_Update
;   X=$09 Pcm_PlayFullVol               X=$18/$1B Pcm_Play (pending drum)
;   X=$0C/$0F/$12/$15 Sfx_PlaySq1/Sq2/Tri/Noise ($3F = sound effect id)
;=============================================================================

.setcpu "6502"

;-----------------------------------------------------------------------------
; RAM
;-----------------------------------------------------------------------------
PpuCtrlCopy            = $09    ; game: shadow of PPU_CTRL
GameLevel              = $10    ; game: current level (selects the raster budget)
FarCallLo              = $13    ; bank-call vector (game)
SfxHdrPtr              = $1D    ; Sfx_Play: temporary pointer (saved/restored)
SfxHdrPtrHi            = $1E
Rng0                   = $2C    ; random generator state
Rng1                   = $2D
Rng2                   = $2E
Rng3                   = $2F    ; incremented after every PCM sample
TempoAcc               = $39    ; tempo accumulator (also: song number passed to Music_Init)
Tempo                  = $3A    ; song tempo (even); added to TempoAcc every frame
TickFlag               = $3B    ; bit 7 set on tick frames
LagMode                = $3C    ; 0 = normal; 1/$81 = Sq2+Noise tick one frame after Sq1+Tri
DataPtr                = $3D    ; track/SFX data pointer (2 bytes)
DataPtrHi              = $3E
Temp                   = $3F    ; scratch; SFX number passed to Sfx_Play*
Temp2                  = $40    ; scratch / command vector / last reg3
Temp3                  = $41
UpdateMode             = $44    ; A given to the bank-0 sound call; $10 = in-level raster mode
PcmDelay               = $45    ; PCM sample delay (rate)
PcmRequest             = $46    ; bit 7 = PCM sound pending, bits 0-6 = generator id 1-5
PcmIndex               = $47
PcmFlipRate            = $48
PcmMask                = $49
PcmFlipAcc             = $4A
PcmOutVec              = $4B
PcmOutVecHi            = $4C
PcmTmp                 = $4D
PcmCount               = $4E
PcmAccelLo             = $4F
PcmAccelHi             = $50
PcmVelLo               = $51
PcmVel                 = $52
PcmLevelLo             = $53
PcmLevel               = $54
PcmSegLimit            = $55
PcmSegCount            = $56
SplitMask              = $57    ; game: $2002 bit to wait for (sprite-0 hit) during PCM
SplitWait              = $59    ; game: samples before polling; $FF = split done
RasterBudget           = $FA    ; delay units left after the update (raster mode)
ChActive               = $0301    ; per channel, stride 4 (x = 0 Sq1, 4 Sq2, 8 Tri, 12 Noise); 0 = off
ChDurCnt               = $0302    ; ticks until next event
ChPtrLo                = $0303    ; track pointer
ChPtrHi                = $0304
SfxId                  = $0311    ; SFX playing on this channel (even id; bit 0 = flag cleared by $02)
SfxTimer               = $0312    ; high nibble = frames left, low nibble = reload
SfxPtrLo               = $0313
SfxPtrHi               = $0314
ChReg0                 = $0321    ; duty / flags (bits 5-7 used)
ChReg1                 = $0322    ; sweep
ChPerLo                = $0323    ; period low
ChPerHi                = $0324    ; period high + length counter
SfxReg0                = $0331
SfxReg1                = $0332
SfxReg2                = $0333
SfxReg3                = $0334
ChRepPtrLo             = $0341    ; REPEAT_CALL: pointer to the call operand
ChRepPtrHi             = $0342
ChRepCount             = $0343
ChVibDelta             = $0344    ; vibrato: current period delta
ChFixDur               = $0351    ; nonzero = all notes use this duration (no duration byte)
ChVolume               = $0352    ; current volume ($10 = constant-volume flag + 0-15)
ChEnvDelay             = $0353    ; envelope: delay before ramp / tremolo half-period
ChTranspose            = $0354    ; added to every note
ChVibWidth             = $0361    ; vibrato: steps per half cycle (0 = off)
ChVibCount             = $0362
ChVibSpeed             = $0363    ; frames per step (+1)
ChVibTimer             = $0364
ChAttack               = $0371    ; bit 7 set = restart volume envelope at each note from this volume
ChEnvTimer             = $0373
ChSlideTimer           = $0374
ChSlideCount           = $0381    ; pitch slide: steps left
ChSlideDelay           = $0382    ; pitch slide: frames before it starts
ChSlideStep            = $0383    ; pitch slide: signed period delta per step
ChSlideRev             = $0384    ; pitch slide: initial steps taken in the opposite direction
ChEnvTarget            = $0391    ; envelope: target volume (mode 1) / delta (mode 2)
ChEnvCount             = $0392
ChEnvMode              = $0393    ; 0 = off, 1 = ramp to target, 2 = tremolo
ChEnvSpeed             = $0394    ; frames per step (+1)
ChSlideSpeed           = $03A1    ; frames per slide step (+1); 0 = slide off
ChLoopDepth            = $03A2    ; REPEAT_CALL nesting: $FD = none, 0, 3, 6 ...
ChEchoXor              = $03A3    ; bit 7 set = echo off; CALL stores the return high byte here
ChEchoVol              = $03A4    ; echo volume; CALL stores the return low byte here
SaveY                  = $03B1
LoopStack              = $0600    ; REPEAT_CALL stack, 15 bytes per channel

;-----------------------------------------------------------------------------
; Hardware and code outside the disassembled range
;-----------------------------------------------------------------------------
PPU_CTRL               = $2000
PPU_STATUS             = $2002
SQ1_VOL                = $4000
SQ1_SWEEP              = $4001
SQ1_LO                 = $4002
SQ1_HI                 = $4003
DMC_RAW                = $4011
FarCall_Return         = $FFE1
DelayYX                = $FFEB

; ----------------------------------------------------------------------------
; Track commands ($00-$7F)
CMD_END              = $00   ; 0 parameter byte(s)
CMD_JUMP             = $01   ; 2 parameter byte(s)
CMD_SFX_CLRFLAG      = $02   ; 0 parameter byte(s)
CMD_INSTR            = $03   ; 3 parameter byte(s)
CMD_HOLD             = $04   ; 0 parameter byte(s)
CMD_REPEAT_END       = $05   ; 0 parameter byte(s)
CMD_FIXDUR           = $06   ; 1 parameter byte(s)
CMD_FIXDUR_OFF       = $07   ; 0 parameter byte(s)
CMD_VIBRATO          = $08   ; 3 parameter byte(s)
CMD_VIBRATO_OFF      = $09   ; 0 parameter byte(s)
CMD_SLIDE_UP         = $0A   ; 5 parameter byte(s)
CMD_SLIDE_DOWN       = $0B   ; 5 parameter byte(s)
CMD_VOLUME_BAD       = $0C   ; 0 parameter byte(s)
CMD_ENV_PRESET       = $0D   ; 1 parameter byte(s)
CMD_TREMOLO          = $0E   ; 3 parameter byte(s)
CMD_VOL_ENV_OFF      = $0F   ; 0 parameter byte(s)
CMD_TEMPO            = $10   ; 1 parameter byte(s)
CMD_TEMPO_ADD        = $11   ; 1 parameter byte(s)
CMD_TRANSPOSE        = $12   ; 1 parameter byte(s)
CMD_TRANSPOSE_ADD    = $13   ; 1 parameter byte(s)
CMD_TRANSPOSE_ALL    = $14   ; 1 parameter byte(s)
CMD_ATTACK_OFF       = $15   ; 0 parameter byte(s)
CMD_ATTACK_PRESET    = $16   ; 1 parameter byte(s)
CMD_VIBRATO_DLY      = $17   ; 4 parameter byte(s)
CMD_PCM_TONE         = $18   ; 1 parameter byte(s)
CMD_PCM_NOISE        = $19   ; 1 parameter byte(s)
CMD_PCM_WAVE_A       = $1A   ; 1 parameter byte(s)
CMD_PCM_WAVE_B       = $1B   ; 1 parameter byte(s)
CMD_PCM_SETUP        = $1C   ; 3 parameter byte(s)
CMD_PCM_WAVE_C       = $1D   ; 1 parameter byte(s)
CMD_REPEAT_CALL      = $1E   ; 3 parameter byte(s)
CMD_CALL             = $1F   ; 2 parameter byte(s)
CMD_RET              = $20   ; 0 parameter byte(s)
CMD_ECHO             = $21   ; 2 parameter byte(s)
CMD_ECHO_OFF         = $22   ; 0 parameter byte(s)
CMD_FIXDUR_ECHO_OFF  = $23   ; 0 parameter byte(s)
CMD_ECHO_TOGGLE      = $24   ; 0 parameter byte(s)
CMD_ATTACK_P         = $25   ; +0..14: attack preset (no parameter)
CMD_VOL              = $34   ; +0..15: set volume (no parameter)
CMD_HWLEN            = $44   ; +0..8: hw length; +9..15: hw length + reg0 byte

; Note bytes ($80-$FF). Pulse/triangle: $81 = C2. Noise: NZ+n = period index n.
REST = $80
N_C2   = $81
N_CS2  = $82
N_D2   = $83
N_DS2  = $84
N_E2   = $85
N_F2   = $86
N_FS2  = $87
N_G2   = $88
N_GS2  = $89
N_A2   = $8A
N_AS2  = $8B
N_B2   = $8C
N_C3   = $8D
N_CS3  = $8E
N_D3   = $8F
N_DS3  = $90
N_E3   = $91
N_F3   = $92
N_FS3  = $93
N_G3   = $94
N_GS3  = $95
N_A3   = $96
N_AS3  = $97
N_B3   = $98
N_C4   = $99
N_CS4  = $9A
N_D4   = $9B
N_DS4  = $9C
N_E4   = $9D
N_F4   = $9E
N_FS4  = $9F
N_G4   = $A0
N_GS4  = $A1
N_A4   = $A2
N_AS4  = $A3
N_B4   = $A4
N_C5   = $A5
N_CS5  = $A6
N_D5   = $A7
N_DS5  = $A8
N_E5   = $A9
N_F5   = $AA
N_FS5  = $AB
N_G5   = $AC
N_GS5  = $AD
N_A5   = $AE
N_AS5  = $AF
N_B5   = $B0
N_C6   = $B1
N_CS6  = $B2
N_D6   = $B3
N_DS6  = $B4
N_E6   = $B5
N_F6   = $B6
N_FS6  = $B7
N_G6   = $B8
N_GS6  = $B9
N_A6   = $BA
N_AS6  = $BB
N_B6   = $BC
NZ     = $C1

;=============================================================================
.segment "SOUND"    ; $8952-$B360 (bank 3)
;=============================================================================


; ----------------------------------------------------------------------------
; PCM ("digital") sound player - same generators as Battletoads, but the
; output routine also performs the game's sprite-0 raster split, because a
; PCM sound now owns the main thread for the rest of the frame.
;   id 1 = PcmGen_Tone (kick/tom), id 2 = PcmGen_Noise, id 3-5 = PcmGen_Wave
; ----------------------------------------------------------------------------
Pcm_PlayFullVol:
        lda #$03                    ; $8952
        jsr Pcm_SetVolume           ; $8954
        lda PcmRequest              ; $8957
        and #$7F                    ; $8959
        jmp Pcm_Dispatch            ; $895B

Pcm_Play:
        lda PcmRequest              ; $895E
        and #$7F                    ; $8960
        sta PcmRequest              ; $8962

Pcm_Dispatch:
        tay                         ; $8964
        lda PcmSegLimit             ; $8965
        sta PcmSegCount             ; $8967
        lda PcmStartIdx,y           ; $8969
        sta PcmIndex                ; $896C
        dey                         ; $896E
        beq PcmDisp_Tone            ; $896F
        dey                         ; $8971
        beq PcmDisp_Noise           ; $8972

PcmDisp_Wave:
        jmp PcmGen_Wave             ; $8974

PcmDisp_Noise:
        jmp PcmGen_Noise            ; $8977

PcmDisp_Tone:
        jmp PcmGen_Tone             ; $897A
        .byte $00, $00, $00, $44                 ; ids 1-4 (id 0 = jmp operand above, id 5 = the CLC below = $18)

; A = 0-3: output volume. Sets PcmOutVec.
Pcm_SetVolume:
        clc                         ; $8981
        adc #<PcmOut_Vol0           ; $8982
        sta PcmOutVec               ; $8984
        lda #>PcmOut_Vol0           ; $8986
        adc #$00                    ; $8988
        sta PcmOutVecHi             ; $898A
        rts                         ; $898C

Pcm_Output:
        jmp (PcmOutVec)             ; $898D

; Sample output (3/2/1/0 right shifts), delay, then fall into Pcm_SplitPoll.
PcmOut_Vol0:
        lsr a                       ; $8990

PcmOut_Vol1:
        lsr a                       ; $8991

PcmOut_Vol2:
        lsr a                       ; $8992

PcmOut_Vol3:
        sta DMC_RAW                 ; $8993
        ldx PcmDelay                ; $8996  delay: 5 cycles per count

PcmOut_Delay:
        dex                         ; $8998
        bne PcmOut_Delay            ; $8999
        inc Rng3                    ; $899B

; Raster split during PCM: after SplitWait samples, wait for the $2002 bit in
; SplitMask (sprite-0 hit); then set PPU_CTRL = $80 for the lower screen
; and disarm (SplitMask = 0, SplitWait = $FF).
Pcm_SplitPoll:
        lda SplitWait               ; $899D
        bmi SplitPoll_Rts           ; $899F
        bne SplitPoll_Count         ; $89A1
        lda SplitMask               ; $89A3
        and PPU_STATUS              ; $89A5  sprite-0 hit yet?
        beq SplitPoll_Rts           ; $89A8
        lda #$80                    ; $89AA
        sta PPU_CTRL                ; $89AC  switch PPU_CTRL for the lower part of the screen
        and #$7F                    ; $89AF
        sta PpuCtrlCopy             ; $89B1
        stx SplitMask               ; $89B3

SplitPoll_Count:
        dec SplitWait               ; $89B5

SplitPoll_Rts:
        rts                         ; $89B7

; PCM "wave" generator data (ids 3, 4, 5). Each byte is one ramp segment:
;   len = byte AND mask (mask $1F for id 3, $0F otherwise), slope = byte >> 5 (id 3)
;   or byte >> 4; successive segments alternate direction (up, down, up, ...).
;   $00,m  sets the noise mask (random AND m is XORed into every sample);
;   $00,$00 ends the sound.
; PCM_WAVE_A (id 3) starts here; 5-bit length, 3-bit slope
PcmWaveTbl:
        .byte $00, $0F                           ; noise mask $0F
        .byte $8F, $98
        .byte $00, $10                           ; noise mask $10
        .byte $D3, $7D, $22, $03, $D4
        .byte $00, $0F                           ; noise mask $0F
        .byte $02, $22, $98, $8F, $01, $74, $98, $9A
        .byte $75, $7B, $79

; PCM_WAVE_C (id 5) starts here; 4-bit length, 4-bit slope
        .byte $9D, $7D, $9A, $5F
        .byte $00, $07                           ; noise mask $07
        .byte $7C, $53, $4C, $0F, $52, $34, $3C, $0F
        .byte $30, $12, $12, $01, $38, $1F
        .byte $00, $03                           ; noise mask $03
        .byte $50, $18, $2C, $0E, $30, $18, $6C, $67
        .byte $35, $18, $3F, $34, $57, $34, $2C, $08
        .byte $4E, $4E, $8C, $4F
        .byte $00, $00                           ; end of sound

; PCM_WAVE_B (id 4) starts here; 4-bit length, 4-bit slope
        .byte $00, $0F                           ; noise mask $0F
        .byte $38, $68, $8B, $A7, $73, $68, $E8, $8A
        .byte $85, $53, $43, $D3, $B6, $82, $5C, $E7
        .byte $44, $C1, $78, $22, $6B, $7E, $24, $22
        .byte $AB, $4B, $44, $F4, $F2, $73, $7E, $6E
        .byte $4C, $08, $76, $5F, $6F, $4D, $68, $58
        .byte $34, $13, $F3, $4E, $A1
        .byte $00, $07                           ; noise mask $07
        .byte $32, $88, $B5
        .byte $00, $03                           ; noise mask $03
        .byte $4F, $56, $52, $74
        .byte $00, $01                           ; noise mask $01
        .byte $69, $68, $4D, $3D, $6A, $82, $63, $67
        .byte $48, $56, $4D, $48, $25, $A2, $79, $39
        .byte $F1, $24, $35, $3B, $5B, $3B, $44, $82
        .byte $38, $34, $4C, $3F, $59, $2A, $3A, $3C
        .byte $4E, $48, $2C, $1C, $39, $2A, $2C, $19
        .byte $2E, $2C, $2E, $0F, $18, $18, $2C, $0F
        .byte $11, $0C, $2C, $0E, $1C, $0F, $18, $0C
        .byte $2A, $0F
        .byte $00, $00                           ; end of sound

; PCM "noise" generator data (id 2): amplitude, decay/sample (subtracted from a
; 16-bit amplitude accumulator, 8.8), length in samples (0 = 256). $00 = end.
PcmNoiseTbl:
        .byte $6F, $FF, $04                      ; amp $6F, decay $FF, 4 samples
        .byte $40, $FF, $1C                      ; amp $40, decay $FF, 28 samples
        .byte $13, $48, $40                      ; amp $13, decay $48, 64 samples
        .byte $4F, $FF, $20                      ; amp $4F, decay $FF, 32 samples
        .byte $18, $38, $60                      ; amp $18, decay $38, 96 samples
        .byte $4F, $FF, $20                      ; amp $4F, decay $FF, 32 samples
        .byte $20, $50, $48                      ; amp $20, decay $50, 72 samples
        .byte $30, $00, $18                      ; amp $30, decay $00, 24 samples
        .byte $50, $00, $40                      ; amp $50, decay $00, 64 samples
        .byte $40, $30, $FF                      ; amp $40, decay $30, 255 samples
        .byte $11, $0C, $FF                      ; amp $11, decay $0C, 255 samples
        .byte $00                                ; end

; PCM "tone" generator data (id 1), one entry per parabolic segment.
; byte 0: bit 7 = acceleration bit 0, bits 0-6 = samples the acceleration lasts;
; byte 1: acceleration bits 1-7, sign-magnitude ($80+n = negative). The value
; added to the 16-bit velocity is (+/-)((b1 & $7F) * 2 + b0.7) * 4.
; A new entry is read every time the level crosses a multiple of 64.
PcmToneTbl:
        .byte $10, $7F                           ; len  16, accel +1016
        .byte $07, $F0                           ; len   7, accel -896
        .byte $20, $1E                           ; len  32, accel +240
        .byte $17, $94                           ; len  23, accel -160
        .byte $20, $10                           ; len  32, accel +128
        .byte $17, $8E                           ; len  23, accel -112
        .byte $16, $0C                           ; len  22, accel +96
        .byte $1C, $8A                           ; len  28, accel -80
        .byte $1E, $09                           ; len  30, accel +72
        .byte $28, $87                           ; len  40, accel -56
        .byte $28, $08                           ; len  40, accel +64
        .byte $28, $86                           ; len  40, accel -48
        .byte $28, $07                           ; len  40, accel +56
        .byte $30, $85                           ; len  48, accel -40
        .byte $30, $06                           ; len  48, accel +48
        .byte $38, $85                           ; len  56, accel -40
        .byte $26, $06                           ; len  38, accel +48
        .byte $38, $84                           ; len  56, accel -32
        .byte $27, $05                           ; len  39, accel +40
        .byte $D0, $83                           ; len  80, accel -28
        .byte $40, $03                           ; len  64, accel +24
        .byte $E0, $83                           ; len  96, accel -28
        .byte $60, $03                           ; len  96, accel +24
        .byte $70, $82                           ; len 112, accel -16
        .byte $E0, $02                           ; len  96, accel +20
        .byte $60, $82                           ; len  96, accel -16
        .byte $C0, $02                           ; len  64, accel +20
        .byte $F0, $82                           ; len 112, accel -20
        .byte $F0, $01                           ; len 112, accel +12
        .byte $F0, $82                           ; len 112, accel -20
        .byte $F0, $01                           ; len 112, accel +12
        .byte $D4, $82                           ; len  84, accel -20
        .byte $7F, $01                           ; len 127, accel +8
        .byte $70, $81                           ; len 112, accel -8
        .byte $00                                ; end

; Unreferenced: second terminator byte after PcmToneTbl
Unref_8ADB:
        .byte $00

; Common exit: keep polling until the split has happened (SplitWait < 0),
; then unwind the far call and return to bank 0.
Pcm_Exit:
        lda SplitWait               ; $8ADC
        bmi PcmExit_Return          ; $8ADE
        ldy #$1E                    ; $8AE0  idle until the raster split has been done

PcmExit_Delay:
        dey                         ; $8AE2
        bne PcmExit_Delay           ; $8AE3
        jsr Pcm_SplitPoll           ; $8AE5
        jmp Pcm_Exit                ; $8AE8

PcmExit_Return:
        pla                         ; $8AEB  discard the return into the far-call stub
        pla                         ; $8AEC
        ldy #$00                    ; $8AED
        jmp FarCall_Return          ; $8AEF

; ----------------------------------------------------------------------------
; Generator 1: tone (kick/tom) - noise click, then parabolic arcs
; (see the Battletoads disassembly for the full description).
; ----------------------------------------------------------------------------
PcmGen_Tone:
        ldy #$54                    ; $8AF2

PcmTone_Click:
        jsr Random                  ; $8AF4
        and #$0F                    ; $8AF7
        adc #$3C                    ; $8AF9
        jsr Pcm_Output              ; $8AFB
        dey                         ; $8AFE
        bne PcmTone_Click           ; $8AFF
        sty PcmMask                 ; $8B01
        sty PcmFlipAcc              ; $8B03
        sty PcmAccelLo              ; $8B05
        sty PcmAccelHi              ; $8B07
        sty PcmVelLo                ; $8B09
        sty PcmLevelLo              ; $8B0B
        lda #$F0                    ; $8B0D
        sta PcmVel                  ; $8B0F
        lda #$3F                    ; $8B11
        sta PcmLevel                ; $8B13
        bne PcmTone_NextSeg         ; $8B15

PcmTone_Sample:
        dec PcmCount                ; $8B17
        bmi PcmTone_Coast           ; $8B19  acceleration only for the first PcmCount samples
        lda PcmVelLo                ; $8B1B
        clc                         ; $8B1D
        adc PcmAccelLo              ; $8B1E
        sta PcmVelLo                ; $8B20
        lda PcmVel                  ; $8B22
        adc PcmAccelHi              ; $8B24
        sta PcmVel                  ; $8B26

PcmTone_Coast:
        lda PcmVelLo                ; $8B28
        clc                         ; $8B2A
        adc PcmLevelLo              ; $8B2B
        sta PcmLevelLo              ; $8B2D
        lda PcmLevel                ; $8B2F
        sta PcmTmp                  ; $8B31
        adc PcmVel                  ; $8B33
        sta PcmLevel                ; $8B35
        eor PcmMask                 ; $8B37
        jsr Pcm_Output              ; $8B39
        lda PcmLevel                ; $8B3C
        eor PcmTmp                  ; $8B3E
        and #$40                    ; $8B40  next segment when the level crosses a multiple of 64
        beq PcmTone_Sample          ; $8B42

PcmTone_NextSeg:
        dec PcmSegCount             ; $8B44
        beq PcmTone_Done            ; $8B46
        ldx PcmIndex                ; $8B48
        lda PcmToneTbl,x            ; $8B4A
        sta PcmTmp                  ; $8B4D
        and #$7F                    ; $8B4F
        beq PcmTone_Done            ; $8B51
        sta PcmCount                ; $8B53
        inx                         ; $8B55
        lda #$00                    ; $8B56
        sta PcmAccelHi              ; $8B58
        lda PcmToneTbl,x            ; $8B5A
        bpl L_8B67                  ; $8B5D
        dec PcmAccelHi              ; $8B5F
        lda #$80                    ; $8B61
        sec                         ; $8B63
        sbc PcmToneTbl,x            ; $8B64
L_8B67:
        inx                         ; $8B67
        stx PcmIndex                ; $8B68
        asl PcmTmp                  ; $8B6A
        rol a                       ; $8B6C
        rol PcmAccelHi              ; $8B6D
        asl a                       ; $8B6F
        rol PcmAccelHi              ; $8B70
        asl a                       ; $8B72
        rol PcmAccelHi              ; $8B73
        sta PcmAccelLo              ; $8B75
        lda PcmFlipAcc              ; $8B77
        adc PcmFlipRate             ; $8B79
        sta PcmFlipAcc              ; $8B7B
        bcc PcmTone_Sample          ; $8B7D
        inc PcmMask                 ; $8B7F
        bne PcmTone_Sample          ; $8B81

PcmTone_Done:
        jmp Pcm_Exit                ; $8B83

; ----------------------------------------------------------------------------
; Generator 3/4/5: ramp segments with masked noise.
; ----------------------------------------------------------------------------
PcmGen_Wave:
        ldx #$00                    ; $8B86
        stx PcmFlipAcc              ; $8B88
        ldx #$1F                    ; $8B8A
        cmp #$00                    ; $8B8C  id 3 (start index 0) uses 5-bit lengths
        beq PcmWave_SetMask         ; $8B8E
        ldx #$0F                    ; $8B90

PcmWave_SetMask:
        stx PcmMask                 ; $8B92
        lda #$3F                    ; $8B94
        sta PcmLevel                ; $8B96
        bne PcmWave_NextSeg         ; $8B98

PcmWave_Sample:
        lda PcmVel                  ; $8B9A
        clc                         ; $8B9C
        adc PcmLevel                ; $8B9D
        sta PcmLevel                ; $8B9F
        jsr Random                  ; $8BA1
        and PcmAccelHi              ; $8BA4
        eor PcmLevel                ; $8BA6
        inx                         ; $8BA8  leftover: X is not used here
        jsr Pcm_Output              ; $8BA9
        dec PcmCount                ; $8BAC
        bpl PcmWave_Sample          ; $8BAE

PcmWave_NextSeg:
        dec PcmSegCount             ; $8BB0
        beq PcmTone_Done            ; $8BB2
        ldx PcmIndex                ; $8BB4
        lda PcmWaveTbl,x            ; $8BB6
        bne PcmWave_Segment         ; $8BB9
        lda PcmWaveTbl_1,x          ; $8BBB
        beq PcmTone_Done            ; $8BBE
        sta PcmAccelHi              ; $8BC0
        inx                         ; $8BC2
        inx                         ; $8BC3
        lda PcmWaveTbl,x            ; $8BC4

PcmWave_Segment:
        and PcmMask                 ; $8BC7
        sta PcmCount                ; $8BC9
        lda PcmWaveTbl,x            ; $8BCB
        inx                         ; $8BCE
        stx PcmIndex                ; $8BCF
        lsr a                       ; $8BD1
        lsr a                       ; $8BD2
        lsr a                       ; $8BD3
        lsr a                       ; $8BD4
        ldx PcmMask                 ; $8BD5
        cpx #$0F                    ; $8BD7
        beq PcmWave_SetSlope        ; $8BD9
        lsr a                       ; $8BDB

PcmWave_SetSlope:
        eor PcmFlipAcc              ; $8BDC
        sta PcmVel                  ; $8BDE
        lda PcmFlipAcc              ; $8BE0
        eor #$FF                    ; $8BE2
        sta PcmFlipAcc              ; $8BE4
        jmp PcmWave_Sample          ; $8BE6

; ----------------------------------------------------------------------------
; Generator 2: decaying noise.
; ----------------------------------------------------------------------------
PcmGen_Noise:
        ldy #$00                    ; $8BE9
        beq PcmNoise_NextSeg        ; $8BEB

PcmNoise_Sample:
        lda #$7F                    ; $8BED
        sta PcmTmp                  ; $8BEF
        lda PcmVel                  ; $8BF1

PcmNoise_MaskLoop:
        asl a                       ; $8BF3
        bmi PcmNoise_Rand           ; $8BF4
        lsr PcmTmp                  ; $8BF6
        bcc PcmNoise_MaskLoop       ; $8BF8

PcmNoise_Rand:
        jsr Random                  ; $8BFA
        and PcmTmp                  ; $8BFD

PcmNoise_Mod:
        sbc PcmVel                  ; $8BFF  A = random mod amplitude
        bcs PcmNoise_Mod            ; $8C01
        adc PcmVel                  ; $8C03
        sta PcmTmp                  ; $8C05
        lda PcmVel                  ; $8C07
        eor #$7F                    ; $8C09  centre it: + (127 - amplitude) / 2
        lsr a                       ; $8C0B
        adc PcmTmp                  ; $8C0C
        jsr Pcm_Output              ; $8C0E
        lda PcmVelLo                ; $8C11
        sbc PcmAccelLo              ; $8C13
        sta PcmVelLo                ; $8C15
        bcs L_8C1B                  ; $8C17
        dec PcmVel                  ; $8C19
L_8C1B:
        dec PcmCount                ; $8C1B
        bne PcmNoise_Sample         ; $8C1D

PcmNoise_NextSeg:
        dec PcmSegCount             ; $8C1F
        beq PcmNoise_Done           ; $8C21
        ldx PcmIndex                ; $8C23
        lda PcmNoiseTbl,x           ; $8C25
        beq PcmNoise_Done           ; $8C28
        sta PcmVel                  ; $8C2A
        lda PcmNoiseTbl_1,x         ; $8C2C
        sta PcmAccelLo              ; $8C2F
        lda PcmNoiseTbl_2,x         ; $8C31
        sta PcmCount                ; $8C34
        inx                         ; $8C36
        inx                         ; $8C37
        inx                         ; $8C38
        stx PcmIndex                ; $8C39
        bne PcmNoise_Sample         ; $8C3B

PcmNoise_Done:
        jmp Pcm_Exit                ; $8C3D

; Pseudo-random number generator (Rng0-3). Returns A = Rng0.
Random:
        lda Rng0                    ; $8C40
        eor Rng3                    ; $8C42
        adc Rng2                    ; $8C44
        sta Rng1                    ; $8C46
        lda Rng2                    ; $8C48
        rol a                       ; $8C4A
        sbc Rng3                    ; $8C4B
        sta Rng2                    ; $8C4D
        eor Rng1                    ; $8C4F
        sta Rng0                    ; $8C51
        rts                         ; $8C53

; ============================================================================
; Music_Init: start song TempoAcc ($39). Far-call X=$03.
; Tempo table bit 0 selects LagMode.
; ============================================================================
Music_Init:
        lda TempoAcc                ; $8C54
        tay                         ; $8C56
        asl a                       ; $8C57
        asl a                       ; $8C58
        asl a                       ; $8C59
        sta Temp                    ; $8C5A
        ldx #$00                    ; $8C5C
        stx TempoAcc                ; $8C5E
        stx PcmSegLimit             ; $8C60
        stx PcmFlipRate             ; $8C62
        lda SongTempoTbl,y          ; $8C64
        and #$FE                    ; $8C67  bits 1-7 = tempo
        sta Tempo                   ; $8C69
        lda SongTempoTbl,y          ; $8C6B
        and #$01                    ; $8C6E  bit 0 = LagMode
        sta LagMode                 ; $8C70
        lda #$03                    ; $8C72
        jsr Pcm_SetVolume           ; $8C74

MusicInit_ChLoop:
        tya                         ; $8C77
        sta ChActive,x              ; $8C78
        ldy Temp                    ; $8C7B
        lda SongTrackTbl,y          ; $8C7D
        sta ChPtrLo,x               ; $8C80
        lda SongTrackTbl_Hi,y       ; $8C83
        sta ChPtrHi,x               ; $8C86
        lda #$01                    ; $8C89
        sta ChDurCnt,x              ; $8C8B
        lda #$FD                    ; $8C8E  no REPEAT_CALL nesting yet
        sta ChLoopDepth,x           ; $8C90
        lda #$00                    ; $8C93
        sta ChFixDur,x              ; $8C95
        sta ChVibWidth,x            ; $8C98
        sta ChSlideSpeed,x          ; $8C9B
        sta ChTranspose,x           ; $8C9E
        sta ChAttack,x              ; $8CA1
        sta ChEnvMode,x             ; $8CA4
        sta ChEchoVol,x             ; $8CA7
        lda #$80                    ; $8CAA  echo off
        sta ChEchoXor,x             ; $8CAC
        ldy Temp                    ; $8CAF
        iny                         ; $8CB1
        iny                         ; $8CB2
        sty Temp                    ; $8CB3
        inx                         ; $8CB5
        inx                         ; $8CB6
        inx                         ; $8CB7
        inx                         ; $8CB8
        cpx #$10                    ; $8CB9
L_8CBB:
        bcc MusicInit_ChLoop        ; $8CBB
        rts                         ; $8CBD

; Raster budget per level (read as RasterBudgetTbl-2,x, so levels 0/1 would
; read the two code bytes before it).
RasterBudgetTbl:
        .byte $39, $51, $50, $50, $50, $50, $42, $4F ; levels 2-9

; ============================================================================
; Music_Update: called once per frame from bank 0 ($FF84) with A in
; UpdateMode. In raster mode ($10) the time the update takes is padded to a
; constant: RasterBudget starts from a per-level value, every command executed
; subtracts 3, and the remainder is burned in the DelayYX loop afterwards.
; ============================================================================
Music_Update:
        lda UpdateMode              ; $8CC6
        cmp #$10                    ; $8CC8
        bne MusicUpd_Plain          ; $8CCA
        ldx GameLevel               ; $8CCC
        cpx #$08                    ; $8CCE
        bne MusicUpd_Budget         ; $8CD0
        lda $EA                     ; $8CD2
        and #$7F                    ; $8CD4
        beq MusicUpd_Budget         ; $8CD6
        dex                         ; $8CD8

MusicUpd_Budget:
        lda RasterBudgetTbl_m2,x    ; $8CD9  NB: index is level-2 into the table
        sta RasterBudget            ; $8CDC
        jsr Music_Frame             ; $8CDE
        lda RasterBudget            ; $8CE1  delay = remaining budget * 8 iterations
        asl RasterBudget            ; $8CE3
        rol a                       ; $8CE5
        asl RasterBudget            ; $8CE6
        rol a                       ; $8CE8
        asl RasterBudget            ; $8CE9
        rol a                       ; $8CEB
        and #$07                    ; $8CEC
        tay                         ; $8CEE
        ldx RasterBudget            ; $8CEF
        beq MusicUpd_Delay          ; $8CF1
        iny                         ; $8CF3

MusicUpd_Delay:
        jsr DelayYX                 ; $8CF4
        beq MusicUpd_Rts            ; $8CF7

MusicUpd_Plain:
        jsr Music_Frame             ; $8CF9

MusicUpd_Rts:
        rts                         ; $8CFC

; One frame of music and SFX processing.
Music_Frame:
        lda TempoAcc                ; $8CFD
        clc                         ; $8CFF
        adc Tempo                   ; $8D00
        sta TempoAcc                ; $8D02
        ror a                       ; $8D04  carry (TempoAcc wrapped) -> bit 7 = tick
        sta TickFlag                ; $8D05
        ldx #$00                    ; $8D07

MusicFrm_ChLoop:
        lda ChActive,x              ; $8D09
        beq MusicFrm_Sfx            ; $8D0C
        jsr Music_Channel           ; $8D0E

MusicFrm_Sfx:
        lda SfxId,x                 ; $8D11
        beq MusicFrm_Next           ; $8D14
        jsr Sfx_Update              ; $8D16

MusicFrm_Next:
        inx                         ; $8D19
        inx                         ; $8D1A
        inx                         ; $8D1B
        inx                         ; $8D1C
        cpx #$10                    ; $8D1D
        bcc MusicFrm_ChLoop         ; $8D1F
        lda LagMode                 ; $8D21  LagMode: odd channels tick on the frame after a tick
        beq MusicFrm_Rts            ; $8D23
        ldx #$01                    ; $8D25
        lda TickFlag                ; $8D27
        bpl MusicFrm_SetLag         ; $8D29
        ldx #$81                    ; $8D2B

MusicFrm_SetLag:
        stx LagMode                 ; $8D2D

MusicFrm_Rts:
        rts                         ; $8D2F

; Process one music channel (X = 0/4/8/12), honouring LagMode.
Music_Channel:
        lda LagMode                 ; $8D30
        beq MusCh_Normal            ; $8D32
        bmi MusCh_LagOdd            ; $8D34
        lda TickFlag                ; $8D36
        bpl MusCh_Effects1          ; $8D38
        txa                         ; $8D3A
        and #$04                    ; $8D3B
        beq MusCh_Tick              ; $8D3D

MusCh_Effects1:
        jmp Music_Effects           ; $8D3F

MusCh_LagOdd:
        txa                         ; $8D42
        and #$04                    ; $8D43
        bne MusCh_Tick              ; $8D45
        jmp Music_Effects           ; $8D47

MusCh_Normal:
        lda TickFlag                ; $8D4A
        bmi MusCh_Tick              ; $8D4C
        jmp Music_Effects           ; $8D4E

MusCh_Tick:
        dec ChDurCnt,x              ; $8D51
        bne MusicFrm_Rts            ; $8D54  note still sounding (no effects on tick frames)
        lda #$00                    ; $8D56  a new event cancels any pitch slide
        sta ChSlideSpeed,x          ; $8D58
        lda ChEchoXor,x             ; $8D5B  echo: alternate the volume on every note
        bmi MusCh_Attack            ; $8D5E
        eor ChEchoVol,x             ; $8D60
        sta ChEchoVol,x             ; $8D63
        jsr SetVolume               ; $8D66
        lda #$00                    ; $8D69
        sta ChEnvMode,x             ; $8D6B

MusCh_Attack:
        lda ChAttack,x              ; $8D6E
        beq MusCh_Read              ; $8D71
        and #$7F                    ; $8D73  attack: restart the envelope from the attack volume
        sta ChVolume,x              ; $8D75
        lda #$01                    ; $8D78
        sta ChEnvMode,x             ; $8D7A
        lda ChEnvCount,x            ; $8D7D
        sta ChEnvDelay,x            ; $8D80

MusCh_Read:
        lda ChPtrLo,x               ; $8D83
        sta DataPtr                 ; $8D86
        lda ChPtrHi,x               ; $8D88
        sta DataPtrHi               ; $8D8B

; Read events until a note is found. Commands jump back here.
ReadEvent_Y0:
        ldy #$FF                    ; $8D8D

ReadEvent_Next:
        iny                         ; $8D8F

ReadEvent:
        lda (DataPtr),y             ; $8D90
        bmi Ev_Note                 ; $8D92
        jmp ExecCommand             ; $8D94

Ev_Note:
        cmp #$80                    ; $8D97
        beq Ev_NoteIdx              ; $8D99
        clc                         ; $8D9B
        adc ChTranspose,x           ; $8D9C

Ev_NoteIdx:
        asl a                       ; $8D9F
        sty Temp                    ; $8DA0
        tay                         ; $8DA2
        lda ChVibWidth,x            ; $8DA3
        lsr a                       ; $8DA6
        adc #$00                    ; $8DA7
        sta ChVibCount,x            ; $8DA9
        lda PeriodTbl,y             ; $8DAC
        cpx #$0C                    ; $8DAF  noise channel: period = (note*2 - $82) / 2
        bne Ev_SetPerLo             ; $8DB1
        tya                         ; $8DB3
        beq Ev_SetPerLo             ; $8DB4
        sbc #$82                    ; $8DB6
        lsr a                       ; $8DB8

Ev_SetPerLo:
        sta ChPerLo,x               ; $8DB9
        lda ChPerHi,x               ; $8DBC
        and #$F8                    ; $8DBF  keep the length-counter bits
        cpx #$0C                    ; $8DC1
        beq Ev_SetPerHi             ; $8DC3
        ora PeriodTbl_Hi,y          ; $8DC5

Ev_SetPerHi:
        sta ChPerHi,x               ; $8DC8
        lda SfxId,x                 ; $8DCB
        bne Ev_Duration             ; $8DCE
        jsr WriteRegsForce          ; $8DD0  note-on: write all registers ($4003 always)

Ev_Duration:
        ldy Temp                    ; $8DD3
        lda ChFixDur,x              ; $8DD5  fixed duration, or read a duration byte
        bne Ev_SetDuration          ; $8DD8
        iny                         ; $8DDA
        lda (DataPtr),y             ; $8DDB

Ev_SetDuration:
        sta ChDurCnt,x              ; $8DDD
        iny                         ; $8DE0
        tya                         ; $8DE1
        clc                         ; $8DE2
        adc DataPtr                 ; $8DE3
        sta ChPtrLo,x               ; $8DE5
        lda DataPtrHi               ; $8DE8
        adc #$00                    ; $8DEA
        sta ChPtrHi,x               ; $8DEC
        rts                         ; $8DEF

; Non-tick frame: pitch slide, vibrato and volume envelope, then write the APU.
Music_Effects:
        lda ChPerHi,x               ; $8DF0
        sta Temp2                   ; $8DF3
        lda ChSlideSpeed,x          ; $8DF5
        beq Fx_Vibrato              ; $8DF8
        lda ChSlideDelay,x          ; $8DFA
        beq Fx_SlideStep            ; $8DFD
        dec ChSlideDelay,x          ; $8DFF
        bne Fx_Vibrato              ; $8E02

Fx_SlideStep:
        dec ChSlideTimer,x          ; $8E04
        bne Fx_Vibrato              ; $8E07
        lda ChSlideSpeed,x          ; $8E09
        sta ChSlideTimer,x          ; $8E0C
        dec ChSlideCount,x          ; $8E0F
        bne Fx_SlideApply           ; $8E12
        lda #$00                    ; $8E14
        sta ChSlideSpeed,x          ; $8E16

Fx_SlideApply:
        ldy #$FF                    ; $8E19
        lda ChSlideRev,x            ; $8E1B
        beq Fx_SlideFwd             ; $8E1E
        dec ChSlideRev,x            ; $8E20
        lda ChSlideStep,x           ; $8E23
        sec                         ; $8E26
        sbc #$01                    ; $8E27
        eor #$FF                    ; $8E29
        jmp Fx_SlideSign            ; $8E2B

Fx_SlideFwd:
        lda ChSlideStep,x           ; $8E2E

Fx_SlideSign:
        bmi Fx_SlideAdd             ; $8E31
        iny                         ; $8E33

Fx_SlideAdd:
        clc                         ; $8E34
        adc ChPerLo,x               ; $8E35
        sta ChPerLo,x               ; $8E38
        tya                         ; $8E3B
        adc ChPerHi,x               ; $8E3C
        sta ChPerHi,x               ; $8E3F

Fx_Vibrato:
        lda ChVibWidth,x            ; $8E42
        beq Fx_Envelope             ; $8E45
        dec ChVibTimer,x            ; $8E47
        bne Fx_Envelope             ; $8E4A
        lda ChVibSpeed,x            ; $8E4C
        sta ChVibTimer,x            ; $8E4F
        lda ChPerHi,x               ; $8E52
        and #$07                    ; $8E55
        ora ChPerLo,x               ; $8E57
        beq Fx_Envelope             ; $8E5A
        ldy #$00                    ; $8E5C
        lda ChVibDelta,x            ; $8E5E
        bpl Fx_VibAdd               ; $8E61
        dey                         ; $8E63

Fx_VibAdd:
        clc                         ; $8E64
        adc ChPerLo,x               ; $8E65
        sta ChPerLo,x               ; $8E68
        tya                         ; $8E6B
        adc ChPerHi,x               ; $8E6C
        sta ChPerHi,x               ; $8E6F
        dec ChVibCount,x            ; $8E72
        bne Fx_Envelope             ; $8E75
        lda ChVibWidth,x            ; $8E77
        sta ChVibCount,x            ; $8E7A
        dec ChVibDelta,x            ; $8E7D
        lda ChVibDelta,x            ; $8E80
        eor #$FF                    ; $8E83
        sta ChVibDelta,x            ; $8E85

Fx_Envelope:
        lda ChEnvMode,x             ; $8E88
        beq Fx_Done                 ; $8E8B
        cmp #$02                    ; $8E8D
        beq Fx_EnvStep              ; $8E8F
        lda ChEnvDelay,x            ; $8E91
        cmp #$01                    ; $8E94
        beq Fx_EnvStep              ; $8E96
        dec ChEnvDelay,x            ; $8E98
        bne Fx_Done                 ; $8E9B

Fx_EnvStep:
        dec ChEnvTimer,x            ; $8E9D
        bne Fx_Done                 ; $8EA0
        lda ChEnvSpeed,x            ; $8EA2
        sta ChEnvTimer,x            ; $8EA5
        lda ChEnvMode,x             ; $8EA8
        cmp #$01                    ; $8EAB
        beq Fx_EnvRamp              ; $8EAD
        lda ChVolume,x              ; $8EAF
        clc                         ; $8EB2
        adc ChEnvTarget,x           ; $8EB3
        sta Temp3                   ; $8EB6
        and #$10                    ; $8EB8
        beq Fx_TremoloCount         ; $8EBA
        lda Temp3                   ; $8EBC
        sta ChVolume,x              ; $8EBE

Fx_TremoloCount:
        dec ChEnvCount,x            ; $8EC1
        bne Fx_Done                 ; $8EC4
        lda ChEnvDelay,x            ; $8EC6
        sta ChEnvCount,x            ; $8EC9
        dec ChEnvTarget,x           ; $8ECC
        lda ChEnvTarget,x           ; $8ECF
        eor #$FF                    ; $8ED2
        sta ChEnvTarget,x           ; $8ED4
        jmp Fx_Done                 ; $8ED7

Fx_EnvRamp:
        lda ChVolume,x              ; $8EDA
        cmp ChEnvTarget,x           ; $8EDD
        bcs Fx_EnvDown              ; $8EE0
        inc ChVolume,x              ; $8EE2
        bcc Fx_EnvCheck             ; $8EE5

Fx_EnvDown:
        dec ChVolume,x              ; $8EE7

Fx_EnvCheck:
        lda ChVolume,x              ; $8EEA
        eor ChEnvTarget,x           ; $8EED
        and #$0F                    ; $8EF0
        bne Fx_Done                 ; $8EF2
        sta ChEnvMode,x             ; $8EF4

Fx_Done:
        lda SfxId,x                 ; $8EF7
        beq WriteRegs               ; $8EFA
        rts                         ; $8EFC

; Write the channel shadow registers to the APU ($4003 only when it changed).
WriteRegsForce:
        lda #$FF                    ; $8EFD
        sta Temp2                   ; $8EFF
        lda ChReg1,x                ; $8F01
        sta SQ1_SWEEP,x             ; $8F04

WriteRegs:
        lda ChReg0,x                ; $8F07
        and #$E0                    ; $8F0A
        ora ChVolume,x              ; $8F0C
        sta SQ1_VOL,x               ; $8F0F
        lda ChPerLo,x               ; $8F12
        sta SQ1_LO,x                ; $8F15
        lda ChPerHi,x               ; $8F18
        cmp Temp2                   ; $8F1B  skip $4003 if unchanged (avoids a phase reset)
        beq WriteRegs_Rts           ; $8F1D
        sta SQ1_HI,x                ; $8F1F

WriteRegs_Rts:
        rts                         ; $8F22

; ============================================================================
; Sfx_Play*: start sound effect Temp ($3F) on one channel at once.
; Far-call X=$0C/$0F/$12/$15.
; ============================================================================
Sfx_PlaySq1:
        ldx #$00                    ; $8F23
        beq Sfx_Play                ; $8F25

Sfx_PlaySq2:
        ldx #$04                    ; $8F27
        bne Sfx_Play                ; $8F29

Sfx_PlayTri:
        ldx #$08                    ; $8F2B
        bne Sfx_Play                ; $8F2D

Sfx_PlayNoise:
        ldx #$0C                    ; $8F2F

Sfx_Play:
        lda Temp                    ; $8F31
        cmp SfxId,x                 ; $8F33  same effect already playing: ignore
        beq WriteRegs_Rts           ; $8F36
        pha                         ; $8F38
        and #$FE                    ; $8F39
        tay                         ; $8F3B
        lda #$00                    ; $8F3C
        sta SfxId,x                 ; $8F3E
        lda SfxHdrPtr               ; $8F41
        pha                         ; $8F43
        lda SfxHdrPtrHi             ; $8F44
        pha                         ; $8F46
        lda SfxTbl,y                ; $8F47
        sta SfxHdrPtr               ; $8F4A
        lda SfxTbl_Hi,y             ; $8F4C
        sta SfxHdrPtrHi             ; $8F4F
        ldy #$00                    ; $8F51
        tya                         ; $8F53
        sta ChVibWidth,x            ; $8F54
        lda (SfxHdrPtr),y           ; $8F57
        and #$0F                    ; $8F59
        sta SfxTimer,x              ; $8F5B
        lda (SfxHdrPtr),y           ; $8F5E
        and #$F0                    ; $8F60
        sta SfxReg0,x               ; $8F62
        iny                         ; $8F65
        lda (SfxHdrPtr),y           ; $8F66
        sta SfxReg1,x               ; $8F68
        iny                         ; $8F6B
        lda (SfxHdrPtr),y           ; $8F6C
        sta SfxReg3,x               ; $8F6E
        tya                         ; $8F71
        sec                         ; $8F72
        adc SfxHdrPtr               ; $8F73
        sta SfxPtrLo,x              ; $8F75
        lda SfxHdrPtrHi             ; $8F78
        adc #$00                    ; $8F7A
        sta SfxPtrHi,x              ; $8F7C
        pla                         ; $8F7F
        sta SfxHdrPtrHi             ; $8F80
        pla                         ; $8F82
        sta SfxHdrPtr               ; $8F83
        pla                         ; $8F85
        sta SfxId,x                 ; $8F86
        rts                         ; $8F89

; Per-frame sound effect update (overrides the music on that channel).
Sfx_Update:
        lda SfxTimer,x              ; $8F8A
        sec                         ; $8F8D
        sbc #$10                    ; $8F8E  count frames in the high nibble
        bcc Sfx_Step                ; $8F90
        sta SfxTimer,x              ; $8F92
        rts                         ; $8F95

Sfx_Step:
        asl a                       ; $8F96
        asl a                       ; $8F97
        asl a                       ; $8F98
        asl a                       ; $8F99
        sta Temp                    ; $8F9A
        ora SfxTimer,x              ; $8F9C
        sta SfxTimer,x              ; $8F9F
        lda SfxPtrLo,x              ; $8FA2
        sta DataPtr                 ; $8FA5
        lda SfxPtrHi,x              ; $8FA7
        sta DataPtrHi               ; $8FAA
        ldy #$00                    ; $8FAC

Sfx_ReadStep:
        lda (DataPtr),y             ; $8FAE
        bne Sfx_Event               ; $8FB0
        sta SfxId,x                 ; $8FB2  effect over: hand the channel back to the music
        lda ChActive,x              ; $8FB5
        bne Sfx_RestoreMusic        ; $8FB8

SilenceChannel:
        lda #$10                    ; $8FBA
        sta SQ1_VOL,x               ; $8FBC
        rts                         ; $8FBF

Sfx_RestoreMusic:
        jmp WriteRegsForce          ; $8FC0

Sfx_Event:
        cmp #$10                    ; $8FC3
        bcc ExecCommand             ; $8FC5  $01-$0F: command (only $02 and $04 belong here)
        lsr a                       ; $8FC7
        lsr a                       ; $8FC8
        lsr a                       ; $8FC9
        lsr a                       ; $8FCA
        sta Temp                    ; $8FCB
        lda SfxReg0,x               ; $8FCD
        and #$F0                    ; $8FD0
        ora Temp                    ; $8FD2
        sta SfxReg0,x               ; $8FD4
        sta SQ1_VOL,x               ; $8FD7
        lda SfxReg1,x               ; $8FDA
        sta SQ1_SWEEP,x             ; $8FDD
        lda (DataPtr),y             ; $8FE0
        and #$07                    ; $8FE2
        sta Temp                    ; $8FE4
        lda SfxReg3,x               ; $8FE6
        and #$07                    ; $8FE9
        cmp Temp                    ; $8FEB
        beq Sfx_SetLo               ; $8FED
        lda SfxReg3,x               ; $8FEF
        and #$F8                    ; $8FF2
        ora Temp                    ; $8FF4
        sta SfxReg3,x               ; $8FF6
        sta SQ1_HI,x                ; $8FF9

Sfx_SetLo:
        iny                         ; $8FFC
        lda (DataPtr),y             ; $8FFD
        sta SfxReg2,x               ; $8FFF
        sta SQ1_LO,x                ; $9002

Sfx_SavePtr:
        tya                         ; $9005
        sec                         ; $9006
        adc DataPtr                 ; $9007
        sta SfxPtrLo,x              ; $9009
        lda DataPtrHi               ; $900C
        adc #$00                    ; $900E
        sta SfxPtrHi,x              ; $9010
        rts                         ; $9013

; Dispatch command A (< $80) through CmdTbl; costs 3 RasterBudget units.
ExecCommand:
        dec RasterBudget            ; $9014  each command costs 3 budget units
        dec RasterBudget            ; $9016
        dec RasterBudget            ; $9018
        stx Temp                    ; $901A
        asl a                       ; $901C
        tax                         ; $901D
        lda CmdTbl,x                ; $901E
        sta Temp2                   ; $9021
        lda CmdTbl_Hi,x             ; $9023
        sta Temp3                   ; $9026
        ldx Temp                    ; $9028
        jmp (Temp2)                 ; $902A

CmdTbl:
