        .word Cmd_PcmTone                        ; $18 PCM_TONE
        .word Cmd_PcmNoise                       ; $19 PCM_NOISE
        .word Cmd_PcmWaveA                       ; $1A PCM_WAVE_A
        .word Cmd_PcmWaveB                       ; $1B PCM_WAVE_B
        .word Cmd_PcmSetup                       ; $1C PCM_SETUP
        .word Cmd_PcmWaveC                       ; $1D PCM_WAVE_C
        .word Cmd_RepeatCall                     ; $1E REPEAT_CALL
        .word Cmd_Call                           ; $1F CALL
        .word Cmd_Ret                            ; $20 RET
        .word Cmd_Echo                           ; $21 ECHO
        .word Cmd_EchoOff                        ; $22 ECHO_OFF
        .word Cmd_FixDurEchoOff                  ; $23 FIXDUR_ECHO_OFF
        .word Cmd_EchoToggle                     ; $24 ECHO_TOGGLE
        .word Cmd_AttackPreset                   ; $25 ATTACK_P0
        .word Cmd_AttackPreset                   ; $26 ATTACK_P1
        .word Cmd_AttackPreset                   ; $27 ATTACK_P2
        .word Cmd_AttackPreset                   ; $28 ATTACK_P3
        .word Cmd_AttackPreset                   ; $29 ATTACK_P4
        .word Cmd_AttackPreset                   ; $2A ATTACK_P5
        .word Cmd_AttackPreset                   ; $2B ATTACK_P6
        .word Cmd_AttackPreset                   ; $2C ATTACK_P7
        .word Cmd_AttackPreset                   ; $2D ATTACK_P8
        .word Cmd_AttackPreset                   ; $2E ATTACK_P9
        .word Cmd_AttackPreset                   ; $2F ATTACK_PA
        .word Cmd_AttackPreset                   ; $30 ATTACK_PB
        .word Cmd_AttackPreset                   ; $31 ATTACK_PC
        .word Cmd_AttackPreset                   ; $32 ATTACK_PD
        .word Cmd_AttackPreset                   ; $33 ATTACK_PE
        .word Cmd_VolumeN                        ; $34 VOL_0
        .word Cmd_VolumeN                        ; $35 VOL_1
        .word Cmd_VolumeN                        ; $36 VOL_2
        .word Cmd_VolumeN                        ; $37 VOL_3
        .word Cmd_VolumeN                        ; $38 VOL_4
        .word Cmd_VolumeN                        ; $39 VOL_5
        .word Cmd_VolumeN                        ; $3A VOL_6
        .word Cmd_VolumeN                        ; $3B VOL_7
        .word Cmd_VolumeN                        ; $3C VOL_8
        .word Cmd_VolumeN                        ; $3D VOL_9
        .word Cmd_VolumeN                        ; $3E VOL_A
        .word Cmd_VolumeN                        ; $3F VOL_B
        .word Cmd_VolumeN                        ; $40 VOL_C
        .word Cmd_VolumeN                        ; $41 VOL_D
        .word Cmd_VolumeN                        ; $42 VOL_E
        .word Cmd_VolumeN                        ; $43 VOL_F
        .word Cmd_HwLen                          ; $44 HWLEN_0
        .word Cmd_HwLen                          ; $45 HWLEN_1
        .word Cmd_HwLen                          ; $46 HWLEN_2
        .word Cmd_HwLen                          ; $47 HWLEN_3
        .word Cmd_HwLen                          ; $48 HWLEN_4
        .word Cmd_HwLen                          ; $49 HWLEN_5
        .word Cmd_HwLen                          ; $4A HWLEN_6
        .word Cmd_HwLen                          ; $4B HWLEN_7
        .word Cmd_HwLen                          ; $4C HWLEN_8
        .word Cmd_HwLenInstr                     ; $4D HWLEN_INSTR_9
        .word Cmd_HwLenInstr                     ; $4E HWLEN_INSTR_A
        .word Cmd_HwLenInstr                     ; $4F HWLEN_INSTR_B
        .word Cmd_HwLenInstr                     ; $50 HWLEN_INSTR_C
        .word Cmd_HwLenInstr                     ; $51 HWLEN_INSTR_D
        .word Cmd_HwLenInstr                     ; $52 HWLEN_INSTR_E
        .word Cmd_HwLenInstr                     ; $53 HWLEN_INSTR_F

Cmd_End:
        lda #$00                    ; $90D5
        sta ChActive,x              ; $90D7
        jmp SilenceChannel          ; $90DA

Cmd_SfxClrFlag:
        lda SfxId,x                 ; $90DD
        and #$FE                    ; $90E0
        sta SfxId,x                 ; $90E2
        iny                         ; $90E5
        jmp Sfx_ReadStep            ; $90E6

Cmd_FixDurOff:
        lda #$00                    ; $90E9
        sta ChFixDur,x              ; $90EB
        jmp ReadEvent_Next          ; $90EE

Cmd_FixDur:
        iny                         ; $90F1
        lda (DataPtr),y             ; $90F2
        sta ChFixDur,x              ; $90F4
        jmp ReadEvent_Next          ; $90F7

Cmd_Instr:
        iny                         ; $90FA
        lda (DataPtr),y             ; $90FB
        sta ChReg0,x                ; $90FD
        and #$1F                    ; $9100
        jsr SetVolume               ; $9102
        iny                         ; $9105
        lda (DataPtr),y             ; $9106
