; $44-$53: hardware note length. Sets reg0 ($1F, or a parameter for $4D-$53),
; sweep $43, and reg3 from HwLenTbl so the APU length counter cuts notes.
Cmd_HwLen:
        lda #$1F                    ; $9114
        sta ChReg0,x                ; $9116
        jsr SetVolume               ; $9119
        lda #$43                    ; $911C
        sta ChReg1,x                ; $911E
        lda (DataPtr),y             ; $9121

SetHwLen:
        sty Temp                    ; $9123
        sec                         ; $9125
        sbc #$44                    ; $9126
        tay                         ; $9128
        lda HwLenTbl,y              ; $9129
        sta ChPerHi,x               ; $912C
        ldy Temp                    ; $912F
        jmp ReadEvent_Next          ; $9131

Cmd_HwLenInstr:
        lda (DataPtr),y             ; $9134
        pha                         ; $9136
        iny                         ; $9137
        lda (DataPtr),y             ; $9138
        sta ChReg0,x                ; $913A
        and #$1F                    ; $913D
        jsr SetVolume               ; $913F
        lda #$43                    ; $9142
        sta ChReg1,x                ; $9144
        pla                         ; $9147
        bne SetHwLen                ; $9148

SetVolume:
        sta ChVolume,x              ; $914A
        lda ChAttack,x              ; $914D
        bpl SetVolume_Rts           ; $9150
        lda ChVolume,x              ; $9152
        ora #$80                    ; $9155
        sta ChAttack,x              ; $9157

SetVolume_Rts:
        rts                         ; $915A

HwLenTbl:
        .byte $03, $18, $38, $48, $58, $68, $78, $88 ; reg3 for $44-$52 (entry $53 reads the INY below)
        .byte $98, $9A, $48, $18, $28, $03, $38

Cmd_Jump:
        iny                         ; $916A
        lda (DataPtr),y             ; $916B
        sta Temp                    ; $916D
        iny                         ; $916F
        lda (DataPtr),y             ; $9170
        sta DataPtrHi               ; $9172
        lda Temp                    ; $9174
        sta DataPtr                 ; $9176
        jmp ReadEvent_Y0            ; $9178

; REPEAT_CALL with nesting: the previous level is pushed onto LoopStack.
Cmd_RepeatCall:
        lda ChLoopDepth,x           ; $917B
        bmi RepCall_Deeper          ; $917E
        sty SaveY                   ; $9180  already inside a loop: push the outer one
        clc                         ; $9183
        adc LoopStackBase,x         ; $9184
        tay                         ; $9187
        lda ChRepCount,x            ; $9188
        sta LoopStack,y             ; $918B
        lda ChRepPtrLo,x            ; $918E
        sta LoopStack+1,y           ; $9191
        lda ChRepPtrHi,x            ; $9194
        sta LoopStack+2,y           ; $9197
        ldy SaveY                   ; $919A
        lda ChLoopDepth,x           ; $919D

RepCall_Deeper:
        clc                         ; $91A0
        adc #$03                    ; $91A1
        sta ChLoopDepth,x           ; $91A3
        iny                         ; $91A6
        lda (DataPtr),y             ; $91A7
        sta ChRepCount,x            ; $91A9
        iny                         ; $91AC
        tya                         ; $91AD
        clc                         ; $91AE
        adc DataPtr                 ; $91AF
        sta ChRepPtrLo,x            ; $91B1
        lda DataPtrHi               ; $91B4
        adc #$00                    ; $91B6
        sta ChRepPtrHi,x            ; $91B8

JumpToOperand:
        lda (DataPtr),y             ; $91BB
        sta Temp                    ; $91BD
        iny                         ; $91BF
        lda (DataPtr),y             ; $91C0
        sta DataPtrHi               ; $91C2
        lda Temp                    ; $91C4
        sta DataPtr                 ; $91C6
        jmp ReadEvent_Y0            ; $91C8

Cmd_RepeatEnd:
        dec ChRepCount,x            ; $91CB  repeat the call, or continue after it
        beq RepeatEnd_Done          ; $91CE
        lda ChRepPtrLo,x            ; $91D0
        sta DataPtr                 ; $91D3
        lda ChRepPtrHi,x            ; $91D5
        sta DataPtrHi               ; $91D8
        ldy #$00                    ; $91DA
        jmp JumpToOperand           ; $91DC

RepeatEnd_Done:
        lda ChRepPtrLo,x            ; $91DF
        sta DataPtr                 ; $91E2
        lda ChRepPtrHi,x            ; $91E4
        sta DataPtrHi               ; $91E7
        clc                         ; $91E9
        lda ChLoopDepth,x           ; $91EA
        beq RepeatEnd_Pop           ; $91ED
        adc LoopStackBase,x         ; $91EF
        tay                         ; $91F2
        lda LoopStack-3,y           ; $91F3
        sta ChRepCount,x            ; $91F6
        lda LoopStack-2,y           ; $91F9
        sta ChRepPtrLo,x            ; $91FC
        lda LoopStack-1,y           ; $91FF
        sta ChRepPtrHi,x            ; $9202
        lda ChLoopDepth,x           ; $9205

RepeatEnd_Pop:
        sbc #$02                    ; $9208
        sta ChLoopDepth,x           ; $920A
        ldy #$02                    ; $920D
        jmp ReadEvent               ; $920F

Cmd_Call:
        iny                         ; $9212  NB: shares ChEchoVol/ChEchoXor with the echo effect
        tya                         ; $9213
        clc                         ; $9214
        adc DataPtr                 ; $9215
        sta ChEchoVol,x             ; $9217
        lda DataPtrHi               ; $921A
        adc #$00                    ; $921C
        sta ChEchoXor,x             ; $921E
        lda (DataPtr),y             ; $9221
        sta Temp                    ; $9223
        iny                         ; $9225
        lda (DataPtr),y             ; $9226
        sta DataPtrHi               ; $9228
        lda Temp                    ; $922A
        sta DataPtr                 ; $922C
        jmp ReadEvent_Y0            ; $922E

Cmd_Ret:
        lda ChEchoXor,x             ; $9231
        sta DataPtrHi               ; $9234
        lda ChEchoVol,x             ; $9236
        sta DataPtr                 ; $9239
        ldy #$02                    ; $923B
        jmp ReadEvent               ; $923D

Cmd_VibratoDly:
