        jmp ReadEvent_Next          ; $924F

ReadVibrato:
        iny                         ; $9252
        lda (DataPtr),y             ; $9253
        sta ChVibWidth,x            ; $9255
        lsr a                       ; $9258
        sta ChVibCount,x            ; $9259
        iny                         ; $925C
        lda (DataPtr),y             ; $925D
        clc                         ; $925F
        adc #$01                    ; $9260
        sta ChVibSpeed,x            ; $9262
        sta ChVibTimer,x            ; $9265
        iny                         ; $9268
        lda (DataPtr),y             ; $9269
        sec                         ; $926B
        sbc #$01                    ; $926C
        eor #$FF                    ; $926E
        sta ChVibDelta,x            ; $9270
