        adc #$01                    ; $92A0
        sta ChSlideSpeed,x          ; $92A2
        sta ChSlideTimer,x          ; $92A5
        iny                         ; $92A8
        lda (DataPtr),y             ; $92A9
        sta ChSlideCount,x          ; $92AB
