        sta PcmRequest              ; $93E1  request a PCM sound; NMI plays it
        iny                         ; $93E3
        lda (DataPtr),y             ; $93E4
        sta PcmDelay                ; $93E6
        jmp ReadEvent_Next          ; $93E8

Cmd_PcmNoise:
        lda #$82                    ; $93EB
        bne SetPcmRequest           ; $93ED

Cmd_PcmWaveA:
        lda #$83                    ; $93EF
        bne SetPcmRequest           ; $93F1

Cmd_PcmWaveB:
        lda #$84                    ; $93F3
        bne SetPcmRequest           ; $93F5

