        bne SetPcmRequest           ; $93F9

Cmd_PcmSetup:
        iny                         ; $93FB
        lda (DataPtr),y             ; $93FC
        sta PcmFlipRate             ; $93FE
        iny                         ; $9400
        lda (DataPtr),y             ; $9401
        sta PcmSegLimit             ; $9403
        iny                         ; $9405
        lda (DataPtr),y             ; $9406
        jsr Pcm_SetVolume           ; $9408
        jmp ReadEvent_Next          ; $940B

